/** Heap, refcounted closure. `rest` marks a variadic function value.
 * `restAbi: "typed"` spells one trailing typed array in `params`; static
 * call sites pack their surplus arguments into it before `callValue`.
 * An absent `restAbi` is the checked-dynamic
 * JS form: `params` stays the declared non-rest list and the lifted
 * function has one hidden trailing ScrDyn array filled by its boxed call
 * thunk. `argumentsAll` keeps that hidden ABI but fills it with every
 * actual argument, including named positions. The backends therefore
 * still see one fixed native closure ABI;
 * only the frontend's call completion observes variadic source arity. */
| {
    kind: "func";
    params: IrType[];
    ret: IrType;
    rest?: true;
    restAbi?: "typed";
    argumentsAll?: true;
  }
| { kind: "object"; className: string } // heap, refcounted class instance
/** The class STATIC side as a value — `typeof C`, the type of the class
 * name itself and of `new (…) => T` constructor-typed slots. Runtime
 * representation is ScrClassObj: an immortal top-level template or a fresh
 * function-local object owning captured binding boxes. Identity is one
 * pointer comparison; local instances retain their constructor object.
 * Values of `classval:C` are C's class object or a STRICT DESCENDANT's —
 * the object kind's nominal, upcast-only story — and every legal flow

 * so `===`, SameValue and searches compare identity roots). */
| {
    kind: "closure";
    fnName: string;
    captures: string[];
    adapts?: true;
    type: IrType;
    loc: SrcLoc;
  }
/** Indirect call of a func-typed value. Args follow `call`'s convention
 * (callee owns its params, callers pass +1). The callee expression is an
 * ordinary owned temp, released at statement end. receiver supplies the
 * call-time this value; absence means undefined. Evaluate callee, receiver,
 * then args, and restore the ambient receiver before unwinding. */
| {
    kind: "callValue";
    callee: IrExpr;
    receiver?: IrExpr;
    args: IrExpr[];
    type: IrType;
    loc: SrcLoc;
  }
/** The currently-executing closure, as a value (+1). Valid only inside a
 * lifted function. Exists so a named nested function can recurse on itself
 * WITHOUT capturing its own binding — a box holding its own closure would
 * be a reference cycle, which naive RC can never free. */
| { kind: "selfRef"; type: IrType; loc: SrcLoc }
/** `yield e` — only inside generator functions (validated). Stores the
 * operand in the generator's out-slot (moved in, typed `yieldT`; null =
 * `yield;`, the undefined arm — the frontend guarantees yieldT admits
 * it) and switches back to the resumer; the expression's value is the

    if (
      !restOk ||
      e.type.params.length !== declared.length ||
      !e.type.params.every((p, i) => typeEquals(p, declared[i]!.type)) ||
      !typeEquals(e.type.ret, wantRet)
    ) {
      err(`closure ${e.fnName}: func type does not match target signature`, e.loc);
    }
  }
  break;
}
case "callValue": {
  checkExpr(e.callee);
  if (e.receiver !== undefined) {
    checkExpr(e.receiver);
    expectType(e.receiver, DYN, "callValue receiver");
  }
  for (const a of e.args) checkExpr(a);
  if (e.callee.type.kind !== "func") {
    err(`callValue callee is ${e.callee.type.kind}, not func`, e.loc);
    break;
  }
  const ft = e.callee.type;
  if (ft.params.length !== e.args.length) {
    err(`callValue: ${e.args.length} args, expected ${ft.params.length}`, e.loc);
  }

case "callValue": {
  // Calling through a closure value: load the fn pointer, pass the
  // closure itself first (the callValue ABI), then the declared
  // params — callees own their refcounted params.
  if (e.callee.type.kind !== "func")
    throw new InternalCompilerError("llvm emitter bug: callValue on non-func");
  const ft = e.callee.type;
  if (e.args.length !== ft.params.length)
    throw new LlvmUnsupportedError("callValue:arity", e.loc);
  // A receiver that reads the ambient `this` binds what the callee
  // would see without a binding: the call forwards it unchanged and
  // needs no receiver bracket (signature adapters forward this way).
  const forwardsReceiver =
    e.receiver?.kind === "libCall" &&
    e.receiver.fn === "dyn.this" &&
    e.receiver.args.length === 0;
  const callee =
    host.stackCallbacks.emit(host, e.callee) ??
    (lendsCallee(host, e, forwardsReceiver)
      ? host.emitReadReceiver(e.callee)
      : emitBorrowedInput(host, e.callee));
  // A class instance bound as the callee's `this` (`h.fn(x)`) is boxed
  // only if the callee reads it: the receiver window records the
  // instance (owned by this frame for the whole call) with its typed-ref
  // recipe, and dyn.this builds the box on first read.
  const lazyReceiver =
    e.receiver?.kind === "dynFrom" &&
    e.receiver.value.type.kind === "object" &&
    isDynTypedRefType(e.receiver.value.type) &&
    !host.shapeHost.isErrorClass(e.receiver.value.type.className)
      ? host.emitExpr(e.receiver.value)
      : null;
  const receiver =
    e.receiver === undefined || lazyReceiver || forwardsReceiver
      ? null
      : host.emitExpr(e.receiver);
  const pushReceiver = (): void => {
    if (lazyReceiver) {
      const t = lazyReceiver.type;
      const recipe = typedRefRecipe(host, t);
      host.declare("declare void @scr_dyn_this_push_typed(ptr, ptr)");
      B.line(`call void @scr_dyn_this_push_typed(ptr ${lazyReceiver.name}, ptr ${recipe})`);
      return;
    }
    host.declare("declare void @scr_dyn_this_push_dyn(ptr)");
    B.line(`call void @scr_dyn_this_push_dyn(ptr ${receiver?.name ?? "null"})`);
  };
  const target = host.knownCallbackTarget(e.callee);
  const known = target?.known;
  const direct = target?.direct;
  // A known closure body that borrows reference parameters is entered
  // directly with lent arguments, as a direct call to a borrowing body
  // is: an argument is read without a reference when neither a later
  // argument nor the body can write what it was read from, and any
  // other value stays owned by this frame until the call returns. The
  // fallback through the closure's own entry passes owned values.
  //
  // An unknown closure is entered through its borrowing entry
  // (ScrClosure.fn_borrowed, which lends every reference argument) when
  // it has one and every reference argument can be lent across any of
  // the call's possible targets.
  // A declared function as a value lends through its interned closure's
  // borrowing wrapper, when it has one.
  let lent =
    known === undefined
      ? undefined
      : known.captures !== undefined
        ? host.callLifetimes.borrowed.get(known.name)
        : host.lendsEveryArgument(known.name)
          ? host.callLifetimes.borrowed.get(known.name)
          : undefined;
  let lend = lent
    ? borrowableInputs(host, e.args, false, host.referenceWrites?.summary(known!.name))
    : [];
  let dynamic = false;
  if (!direct && (e.receiver === undefined || forwardsReceiver)) {
    const references = new Set<number>();
    ft.params.forEach((param, index) => {
      if (isRefCounted(param)) references.add(index);
    });
    if (references.size > 0) {
      const inputs = borrowableInputs(host, e.args, false, host.referenceWrites?.ownWrites(e));
      if ([...references].every((index) => inputs[index] === true)) {
        lent = references;
        lend = inputs;
        dynamic = true;
      }
    }
  }
  if (lent) host.frames.push([]);
  const args = e.args.map((a, i) =>
    lent?.has(i) && lend[i] ? host.emitReadReceiver(a) : host.emitExpr(a),
  );
  args.forEach((a, i) => {
    if (!lent?.has(i)) host.toFrame(a);
  });
  const argListOf = (values: readonly LlValue[]): string =>
    [
      `ptr ${callee.name}`,
      ...values.map((a, i) => `${host.llType(ft.params[i]!)} ${a.name}`),
    ].join(", ");
  // The owned entry consumes a reference of each lent argument.
  const ownedArgs = (): LlValue[] =>
    lent
      ? args.map((a, i) =>
          lent.has(i) ? { name: host.retainFrame(a.name, a.type), type: a.type } : a,
        )
      : args;
  // An entry through the closure's own pointer brackets the call only
  // when the closure may observe the receiver (SCR_CLOSURE_KIND_RECEIVER_FREE).
  const invoke = (
    target: string,
    bracket: boolean,
    values = args,
    indirect = false,
  ): string => {
    const needsReceiver = bracket && !forwardsReceiver;
    let observes: string | null = null;
    if (needsReceiver) {
      host.declare("declare void @scr_dyn_this_pop()");
      if (indirect) {
        const kindPtr = B.tmp(),
          kind = B.tmp(),
          free = B.tmp();
        observes = B.tmp();
        B.line(
          `${kindPtr} = getelementptr inbounds %ScrClosure, ptr ${callee.name}, i64 0, i32 4`,
        );
        B.line(`${kind} = load i32, ptr ${kindPtr}`);
        B.line(`${free} = and i32 ${kind}, ${CLOSURE_KIND.RECEIVER_FREE}`);
        B.line(`${observes} = icmp eq i32 ${free}, 0`);
        const push = B.newLabel("receiver.push"),
          pushed = B.newLabel("receiver.call");
        B.condBr(observes, push, pushed);
        B.startBlock(push);
        pushReceiver();
        B.br(pushed);
        B.startBlock(pushed);
      } else pushReceiver();
    }
    const result = e.type.kind === "void" ? "" : B.tmp();
    B.line(
      `${result ? `${result} = ` : ""}call ${host.llType(e.type)} ${target}(${argListOf(values)})`,
    );
    if (observes !== null) {
      const pop = B.newLabel("receiver.pop"),
        popped = B.newLabel("receiver.done");
      B.condBr(observes, pop, popped);
      B.startBlock(pop);
      B.line("call void @scr_dyn_this_pop()");
      B.br(popped);
      B.startBlock(popped);
    } else if (needsReceiver) B.line("call void @scr_dyn_this_pop()");
    return result;
  };
  // The direct entry of a known target brackets the call when the target
  // may observe the receiver. A signature adapter that only forwards the
  // receiver to its original carries the original's RECEIVER_FREE bit
  // (set where the adapter closure is built), so its entry tests the bit,
  // like the entry through the closure's own pointer.
  const invokeKnown = (target: string): string => {
    const readers = host.receiverReaders;
    if (readers.ignores(known!)) return invoke(target, false);
    return invoke(target, true, args, readers.forwardsOnly(known!));
  };
  const lending =
    lent && !dynamic
      ? known!.captures !== undefined
        ? `@${mangleBorrowedFunction(known!.name)}`
        : `@${mangleBorrowingWrapper(known!.name)}`
      : undefined;

/* scriptc runtime — boxes and closures (scr_closure.c). Included by
 * scr_runtime.h, which says where new declarations go. */
#ifndef SCR_CLOSURE_H
#define SCR_CLOSURE_H

#include "scr_map.h"

/* ── closures ───────────────────────────────────────────────────────
 * A closure is a function pointer plus the boxes of its captured bindings.
 * A box is one shared, refcounted variable cell: every function that
 * captures a binding (and the function that declared it) reads and writes
 * the same box, which is what makes mutation through a closure visible
 * everywhere (JS shared-binding semantics).
 *
 * The compiler emits the callee's C signature as (ScrClosure *env, params…);
 * the callee borrows env->caps[] (the closure owns them). rc == SIZE_MAX
 * marks an immortal closure (the compiler interns one per top-level
 * function referenced as a value, so `f === f` is true like in JS).
 *
 * Ownership: box _get_ref returns +1; _set_ref releases the old value and
 * takes ownership of the new one; releasing a box releases its contents;
 * releasing a closure releases its boxes.
 */

typedef enum {
  SCR_BOX_F64,
  SCR_BOX_BOOL,
  SCR_BOX_STR,
  SCR_BOX_ARR,
  SCR_BOX_FUNC,
  SCR_BOX_OBJ, /* class instance: retain/release via the fn ptrs below */
} ScrBoxKind;

typedef struct ScrBox {
  size_t rc;
  ScrBoxKind kind;
  /* SCR_BOX_OBJ only: class instances are per-class C structs the runtime
   * knows nothing about, so the compiler supplies their RC entry points.
   * obj_trace is non-NULL exactly when the payload type carries a cycle
   * header (the box's own trace then visits the payload; NULL means the
   * payload is acyclic and the box releases it itself at teardown). */
  void *(*obj_retain)(void *);
  void (*obj_release)(void *);
  ScrTraceFn obj_trace;
  uint64_t slot; /* double/bool/pointer via memcpy and casts */
} ScrBox;

/* A box can lie on a cycle only when its trace visits its payload: a
 * closure, or a class instance that carries a cycle header. Every other box
 * is a leaf of the object graph, so its releases buffer no candidate. The
 * emitted inline release (llvm/shapes.ts, the box row) mirrors this test,
 * reading `kind` and `obj_trace` at the asserted offsets. */
static inline bool scr_box_traced(const ScrBox *b) {
  return b->kind == SCR_BOX_FUNC || b->obj_trace != NULL;
}
_Static_assert(SCR_BOX_FUNC == 4, "the emitted box release compares kind against 4");
#if UINTPTR_MAX == UINT64_MAX
_Static_assert(offsetof(ScrBox, kind) == 8 && offsetof(ScrBox, obj_trace) == 32,
               "the emitted box release reads kind at 8 and obj_trace at 32");
#else
_Static_assert(offsetof(ScrBox, kind) == 4 && offsetof(ScrBox, obj_trace) == 16,
               "the emitted box release reads kind at 4 and obj_trace at 16");
#endif

ScrBox *scr_box_new(ScrBoxKind kind); /* returns +1, slot zeroed */
ScrBox *scr_box_new_obj(void *(*retain)(void *), void (*release)(void *),
                         ScrTraceFn trace);

static inline ScrBox *scr_box_retain(ScrBox *b) {
  if (b->rc != SIZE_MAX) {
    b->rc++;
  }
  return b;
}

void scr_box_release(ScrBox *b); /* releases ref contents by kind; NULL-tolerant */

double scr_box_get_f64(ScrBox *b);
bool scr_box_get_bool(ScrBox *b);
void *scr_box_get_ref(ScrBox *b); /* returns +1 */
void scr_box_set_f64(ScrBox *b, double v);
void scr_box_set_bool(ScrBox *b, bool v);
void scr_box_set_ref(ScrBox *b, void *v); /* releases old, owns new */

